function isISODate(s) {
  return typeof s === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(s);
}

// Get the input data
let rawData = $input.item.json;

// Extract the actual data - the output is a JSON string that needs parsing
let data;
if (rawData.output && typeof rawData.output === 'string') {
  // Parse the JSON string
  data = JSON.parse(rawData.output);
} else if (rawData.output && typeof rawData.output === 'object') {
  data = rawData.output;
} else if (rawData.vendor_name !== undefined) {
  data = rawData;
} else {
  throw new Error('Could not find data in expected format');
}

// Extract only the fields we need - ignore any extra keys
const vendor_name = data.vendor_name ?? null;
const expense_date = data.expense_date ?? null;
const total_amount = (data.total_amount === null || data.total_amount === undefined) ? null : Number(data.total_amount);
const tax_amount = (data.tax_amount === null || data.tax_amount === undefined) ? null : Number(data.tax_amount);
const currency = data.currency ?? 'USD';

// Check that required fields exist
const required = ['vendor_name', 'expense_date', 'total_amount', 'tax_amount', 'currency'];
for (const field of required) {
  if (!(field in data)) throw new Error(`Missing required field: ${field}`);
}

// Basic validation
if (expense_date !== null && !isISODate(expense_date)) throw new Error('expense_date not ISO YYYY-MM-DD');
if (total_amount !== null && !Number.isFinite(total_amount)) throw new Error('total_amount not a number');
if (tax_amount !== null && !Number.isFinite(tax_amount)) throw new Error('tax_amount not a number');

return { vendor_name, expense_date, total_amount, tax_amount, currency };

// Try to get OCR confidence from the workflow trigger or use a default
const ocr_conf = 0.75; // Default confidence if not available from previous node

const required = ['vendor_name','expense_date','total_amount'];
let present = 0;
for (const k of required) {
  if ($json[k] !== null && $json[k] !== undefined && $json[k] !== '') present++;
}

const field_completeness = present / required.length;
const confidence_score = (ocr_conf * 0.4) + (field_completeness * 0.6);

// Gate
const needs_review = confidence_score < 0.85 || present < required.length;

return [{
  ...$json,
  confidence_score,
  needs_review
}];

