// Allow short or missing raw_text since we're using structured OCR
if ($json.raw_text && $json.raw_text.length < 10) {
  throw new Error("RAW_TEXT_TOO_SHORT");
}

if (!$json.org_id || !$json.document_id) {
  throw new Error("MISSING_CONTEXT");
}

const ocr_conf = Number($json.ocr_confidence ?? 0.95);
if (Number.isNaN(ocr_conf)) {
  throw new Error("OCR_CONFIDENCE_NOT_NUMERIC");
}

return {
  ...$json,
  ocr_confidence: ocr_conf,
  raw_text: $json.raw_text || JSON.stringify($json.textract_response || {})
};

function numOrNull(v) {
  if (v === null || v === undefined || v === '' || v === 'null') {
    return null;
  }
  const n = Number(v);
  return Number.isFinite(n) ? n : null;
}

function dateOrNull(v) {
  if (!v) return null;

  const s = String(v).replace(/\s+/g, ' ').trim();

  // Remove time portion (DATE column does not need it)
  const datePart = s.split(' ')[0];

  const m = datePart.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})$/);
  if (!m) return null;

  let a = parseInt(m[1], 10);
  let b = parseInt(m[2], 10);
  const year = parseInt(m[3], 10);

  let day, month;

  // Disambiguation
  if (a > 12 && b <= 12) {
    day = a;
    month = b;
  } else if (b > 12 && a <= 12) {
    month = a;
    day = b;
  } else {
    // Ambiguous (both <= 12)
    // Default to US MM/DD — change if needed
    month = a;
    day = b;
  }

  if (month < 1 || month > 12) return null;
  if (day < 1 || day > 31) return null;

  return `${year}-${String(month).padStart(2, '0')}-${String(day).padStart(2, '0')}`;
}

const ctx = $('When Executed by "Doc_OCR_Pipeline_v1_W2"').first().json;

const normalizedDate = dateOrNull($json.expense_date);
const normalizedTotal = numOrNull($json.total_amount);
const normalizedTax = numOrNull($json.tax_amount);

// Auto-force review if critical fields fail validation
const autoNeedsReview =
  !normalizedDate ||
  normalizedTotal === null ||
  normalizedTotal <= 0;

return [{
  json: {
    org_id: ctx.context.org_id ?? null,
    document_id: ctx.document.document_id ?? null,
    project_id: ctx.context.project_id ?? null,
    client_id: ctx.context.client_id ?? null,

    vendor_name: $json.vendor_name ?? null,

    // ISO-safe date for Postgres DATE column
    expense_date: normalizedDate,

    // Preserve raw value for debugging/audit
    expense_date_raw: $json.expense_date ?? null,

    total_amount: normalizedTotal,
    tax_amount: normalizedTax,

    currency: $json.currency ?? 'USD',

    confidence_score: numOrNull($json.confidence_score),

    needs_review: autoNeedsReview
      ? true
      : ($json.needs_review ?? false)
  }
}];

const required = [
  'context.org_id',
  'context.document_id',
  'document.file_path',  // Changed: This is what we need to download from S3
];

for (const path of required) {
  const value = path.split('.').reduce((o, k) => o?.[k], $json);
  if (value === undefined || value === null || value === '') {
    throw new Error(`MISSING_REQUIRED_FIELD:${path}`);
  }
}

return [{ json: $json }];
